// ---------------------------------------------------------------------------
// Scripture reference parser (ExtendScript / ES3).  A line-for-line port of
// scripture_index/parser.py; both are tested against the same cases.
// Requires a global DATA object (generated by the app).
// ---------------------------------------------------------------------------
var SPC = "[ \\u00a0\\u2009\\u202f]";
var DASH = "[\\u2013\\u2014\\-\\u2011]";
var HLET = "\\u05d0-\\u05ea";
var HN = "[" + HLET + "]{1,3}(?:[\\u05f4\"\\u201d][" + HLET + "])?[\\u05f3'\\u2019]?";
var WCLASS = "A-Za-z0-9_\\u00aa\\u00b5\\u00ba\\u00c0-\\u00d6\\u00d8-\\u00f6\\u00f8-\\u02af\\u0370-\\u03ff\\u0400-\\u04ff\\u05d0-\\u05ea";
var WORDRE = new RegExp("[" + WCLASS + "]");
var INDEXED = {"explicit": 1, "chain": 1, "inferred": 1, "inferred-weak": 1, "manual": 1};
var STATUS_LABELS = {
    "explicit": "Book named", "chain": "Book named (list)", "inferred": "Book from context",
    "inferred-weak": "Book from context (distant)", "verse-only": "Verse only",
    "chapter-only": "Chapter only", "italic": "Italic (possible title)",
    "citation": "Volume:page citation", "invalid": "Impossible chapter/verse",
    "unresolved": "No book found", "manual": "Added by hand"
};

function isW(ch) { return ch !== undefined && ch !== null && ch !== "" && WORDRE.test(ch); }
function reEsc(s) { return s.replace(/[.*+?\^${}()|\[\]\\\/\-]/g, "\\$&"); }
function altOf(list) {
    var out = [], i;
    for (i = 0; i < list.length; i++) out.push(reEsc(list[i]));
    return out.length ? out.join("|") : "(?!)";
}
function sortByLenDesc(list) {
    var c = list.slice(0);
    c.sort(function (a, b) { return b.length - a.length; });
    return c;
}
function matchAt(re, text, pos) {           // re must start with ^
    var m = re.exec(text.substring(pos));
    if (!m) return null;
    return {m: m, start: pos, end: pos + m[0].length};
}

// --- Hebrew numerals -------------------------------------------------------
var HVAL = {"א": 1, "ב": 2, "ג": 3, "ד": 4, "ה": 5, "ו": 6, "ז": 7,
    "ח": 8, "ט": 9, "י": 10, "כ": 20, "ך": 20, "ל": 30, "מ": 40,
    "ם": 40, "נ": 50, "ן": 50, "ס": 60, "ע": 70, "פ": 80, "ף": 80,
    "צ": 90, "ץ": 90, "ק": 100, "ר": 200, "ש": 300, "ת": 400};

function hebToInt(s) {
    var t = (s || "").replace(/[׳״'"’”]/g, ""), i, vals = [], sum = 0, head, units = {}, nu = 0, nt = 0;
    if (!t || t.length > 4) return null;
    for (i = 0; i < t.length; i++) {
        if (HVAL[t.charAt(i)] === undefined) return null;
        vals.push(HVAL[t.charAt(i)]);
        sum += HVAL[t.charAt(i)];
    }
    var tail = t.substring(t.length - 2);
    if (tail === "טו" || tail === "טז") {
        head = vals.slice(0, vals.length - 2);
        for (i = 0; i + 1 < head.length; i++) if (head[i] < head[i + 1]) return null;
        if (head.length && head[head.length - 1] < 10) return null;
        return sum;
    }
    for (i = 0; i + 1 < vals.length; i++) if (vals[i] < vals[i + 1]) return null;
    if (t.indexOf("יה") >= 0 || t.indexOf("יו") >= 0) return null;
    for (i = 0; i < t.length; i++) {
        var v = HVAL[t.charAt(i)];
        if (v < 10 && !units[t.charAt(i)]) { units[t.charAt(i)] = 1; nu++; }
        if (v >= 10 && v < 100) nt++;
    }
    if (nu > 1 || nt > 1) return null;
    return sum;
}

function intToHeb(n) {
    var out = "", i, H = [[400, "ת"], [300, "ש"], [200, "ר"], [100, "ק"]];
    var T = [[90, "צ"], [80, "פ"], [70, "ע"], [60, "ס"], [50, "נ"], [40, "מ"],
        [30, "ל"], [20, "כ"], [10, "י"]];
    var U = [[9, "ט"], [8, "ח"], [7, "ז"], [6, "ו"], [5, "ה"], [4, "ד"],
        [3, "ג"], [2, "ב"], [1, "א"]];
    for (i = 0; i < H.length; i++) while (n >= H[i][0]) { out += H[i][1]; n -= H[i][0]; }
    if (n === 15) return out + "טו";
    if (n === 16) return out + "טז";
    for (i = 0; i < T.length; i++) if (n >= T[i][0]) { out += T[i][1]; n -= T[i][0]; break; }
    for (i = 0; i < U.length; i++) if (n >= U[i][0]) { out += U[i][1]; n -= U[i][0]; break; }
    return out;
}

// --- References ------------------------------------------------------------
var SFX_ORDER = {"": 0, "a": 1, "b": 2, "c": 3, "d": 4, "f": 5, "s": 5, "ff": 6, "ss": 6};
function normSfx(s) { return (s || "").replace(/\.+$/, ""); }
function pad3(n) { var s = String(n); while (s.length < 3) s = "0" + s; return s; }

function mkRef(book, c1, v1, s1, c2, v2, s2) {
    return {book: book, c1: c1, v1: v1 || 0, s1: normSfx(s1), c2: c2 || 0, v2: v2 || 0, s2: normSfx(s2)};
}
function bookOf(id) { return DATA.books[id]; }       // [name, section, rank, chapters]
function bookName(id) { var b = bookOf(id); return b ? b[0] : id; }
function numStr(n) { return DATA.numerals === "hebrew" ? intToHeb(n) : String(n); }
function sfxStr(s) { return (s === "f" || s === "ff" || s === "s" || s === "ss") ? s + "." : s; }

function refLabel(r) {
    var sep = DATA.labelSep, b = bookOf(r.book), single = b && b[3] === 1, s, start;
    if (r.v1 === 0) {
        s = numStr(r.c1);
        if (r.c2 && r.c2 !== r.c1) s += "–" + numStr(r.c2);
        return s;
    }
    start = single ? numStr(r.v1) + sfxStr(r.s1) : numStr(r.c1) + sep + numStr(r.v1) + sfxStr(r.s1);
    if (!r.c2) return start;
    if (r.c2 === r.c1 || single) return start + "–" + numStr(r.v2) + sfxStr(r.s2);
    return start + "–" + numStr(r.c2) + sep + numStr(r.v2) + sfxStr(r.s2);
}
function refSortKey(r) {
    var sx = function (s) { return String(SFX_ORDER[s] === undefined ? 0 : SFX_ORDER[s]); };
    var end = r.c2 ? pad3(r.c2) + pad3(r.v2) + sx(r.s2) : "0000000";
    return pad3(r.c1) + pad3(r.v1) + sx(r.s1) + end;
}
function sectionRank(sec) {
    for (var i = 0; i < DATA.sectionOrder.length; i++) if (DATA.sectionOrder[i] === sec) return i + 1;
    return 9;
}
function refBookKey(r) { var b = bookOf(r.book); return String(sectionRank(b[1])) + pad3(b[2]); }
function refDisplay(r) { return bookName(r.book) + " " + refLabel(r); }
function refValid(r) {
    var b = bookOf(r.book), pairs = [[r.c1, r.v1], [r.c2, r.v2]], i;
    if (!b) return false;
    for (i = 0; i < 2; i++) {
        var c = pairs[i][0], v = pairs[i][1];
        if (c === 0) continue;
        if (c > b[3] || c < 1 || v > 176) return false;
    }
    if (r.c2 && (r.c2 < r.c1 || (r.c2 === r.c1 && r.v2 < r.v1))) return false;
    return true;
}

// --- Spellings -------------------------------------------------------------
function normSpelling(s) {
    s = s.replace(/^[\s   ]+|[\s   ]+$/g, "");
    s = s.replace(/[    ]+/g, " ");
    s = s.replace(/'/g, "׳").replace(/’/g, "׳").replace(/"/g, "״").replace(/”/g, "״");
    s = s.replace(/^([123])\.?[    \t\r\n]*(?=\D)/, "$1 ");
    if (s.charAt(s.length - 1) === "." && s.substring(s.length - 2) !== "..") s = s.substring(0, s.length - 1);
    return s;
}
function resolve(text) { var v = DATA.map[normSpelling(text)]; return v ? v : null; }

var _candRe = null;
function candidatesAt(text, pos) {
    var out = [], i, sub = text.substring(pos);
    if (!_candRe) {
        _candRe = [];
        for (i = 0; i < DATA.spell.length; i++)
            _candRe.push(new RegExp("^(?:" + DATA.spell[i][0] + ")(?:\\.)?(?![" + WCLASS + "])"));
    }
    for (i = 0; i < _candRe.length; i++) {
        var m = _candRe[i].exec(sub);
        if (m) out.push({end: pos + m[0].length, info: DATA.map[DATA.spell[i][1]]});
    }
    return out;
}

// --- Patterns ----------------------------------------------------------------
function Patterns() {
    var R = DATA.rules, i, alts = [];
    var seps = "";
    for (i = 0; i < R.cvSeps.length; i++) seps += reEsc(R.cvSeps[i]);
    this.sep = "[" + seps + "]";
    var sf = R.suffixes.slice(0);
    sf.sort(function (a, b) { return b[0].length - a[0].length; });
    for (i = 0; i < sf.length; i++) alts.push(reEsc(sf[i][0]) + "\\.?");
    alts.push("[a-d](?![A-Za-z])");
    this.sfx = "(?:" + alts.join("|") + ")";
    var num = "\\d{1,3}";
    var ands = altOf(R.andWords), cfs = altOf(R.cfWords);
    // groups: 1 c1, 2 v1, 3 s1, 4 x, 5 y, 6 s2
    this.cv = new RegExp("(" + num + ")" + this.sep + "(" + num + ")(" + this.sfx + ")?" +
        "(?:" + SPC + "?" + DASH + SPC + "?(" + num + ")(?:" + this.sep + "(" + num + "))?(" + this.sfx + ")?)?" +
        "(?!\\d)(?!" + this.sep + "\\d)(?!" + SPC + "?(?:[ap]\\.m\\.|[AaPp][Mm]\\b))", "g");
    this.hcv = DATA.numerals === "hebrew" ? new RegExp("^" + SPC + "*(" + HN + ")" + SPC + "*[,:]" + SPC + "*(" + HN + ")" +
        "(?:" + SPC + "*" + DASH + SPC + "*(" + HN + ")(?:" + SPC + "*[,:]" + SPC + "*(" + HN + "))?)?" +
        "(?![" + HLET + "])") : null;
    var vnum = "\\d{1,3}(?:" + this.sfx + ")?(?:" + SPC + "?" + DASH + SPC + "?\\d{1,3}(?:" + this.sfx + ")?)?";
    // groups: 1 word, 2 space, 3 list
    this.vw = new RegExp("(" + altOf(sortByLenDesc(R.verseWords)) + ")(" + SPC + "?)(" + vnum +
        "(?:(?:," + SPC + "?|,?" + SPC + "(?:" + ands + ")" + SPC + ")" + vnum + ")*)(?!\\d)", "g");
    this.vnum = new RegExp("(\\d{1,3})(" + this.sfx + ")?(?:" + SPC + "?" + DASH + SPC + "?(\\d{1,3})(" + this.sfx + ")?)?", "g");
    this.afterCh = new RegExp("^\\.?" + SPC + "+(\\d{1,3})(?:" + SPC + "?" + DASH + SPC + "?(\\d{1,3}))?(?!\\d)(?!" + this.sep + "\\d)");
    this.xch = new RegExp("^\\.?" + SPC + "+(\\d{1,3})" + SPC + "?" + DASH + SPC + "?(\\d{1,3})" + this.sep + "(\\d{1,3})(?!\\d)");
    this.cvNext = new RegExp("^\\.?" + SPC + "*\\d{1,3}" + this.sep + "\\d");
    this.hcvNext = this.hcv ? new RegExp("^" + SPC + "*" + HN + SPC + "*[,:]" + SPC + "*" + HN) : null;
    this.attachedGap = new RegExp("^\\.?" + SPC + "*$");
    this.chainGap = new RegExp("^" + SPC + "*(?:[;,]" + SPC + "*(?:(?:" + cfs + ")" + SPC + "*)?" +
        "|,?" + SPC + "*(?:" + ands + "|or)" + SPC + "+)$");
    var spaced = altOf(R.spaced), tight = altOf(R.tight);
    // groups: 1 lead, 2 v, 3 s, 4 v2, 5 s2
    this.cont = new RegExp("^((?:(?:" + spaced + ")" + SPC + "?|,?" + SPC + "(?:" + ands + ")" + SPC + "|(?:" + tight + ")))" +
        "(\\d{1,3})(" + this.sfx + ")?(?:" + SPC + "?" + DASH + SPC + "?(\\d{1,3})(" + this.sfx + ")?)?(?!\\d)(?!" + this.sep + "\\d)");
    this.contOkAfter = new RegExp("^(?:" + SPC + "*(?:[)\\];,.\\u201d\"\\u2019\\u00bb]|$)|,?" + SPC + "(?:" + ands + ")" + SPC + "\\d|(?:" + tight + ")\\d)");
    this.introBefore = new RegExp("(?:" + altOf(R.intro) + ")" + SPC + "+$");
    var pre = R.prefixLetters ? "((?:[" + R.prefixLetters + "]{1,2})?)" : "()";
    var spell = [];
    for (i = 0; i < DATA.spell.length; i++) spell.push(DATA.spell[i][0]);
    // groups: 1 prefix, 2 name, 3 dot
    this.book = new RegExp(pre + "(" + (spell.length ? spell.join("|") : "(?!)") + ")(\\.)?(?![" + WCLASS + "])", "g");
}

var CITATION_BEFORE = new RegExp("(?:(?:^|[^A-Za-z0-9_])(?:vols?|nos?|pp?|col|cols|Bd|Bde|S|Sp|t|tome)\\." + SPC + "*\\d*,?" + SPC + "*$" +
    "|\\d{4}\\)?[,.]?" + SPC + "*$" +
    "|\\)[,.]?" + SPC + "*$" +
    "|(?:^|[^A-Za-z0-9_])[A-Z]{2,}[A-Za-z]*[,.]?" + SPC + "*$" +
    "|(?:^|[^A-Za-z0-9_\\u00e9])(?:ed|\\u00e9d|Hg|hg)\\.,?" + SPC + "*$)");
var TIME_AFTER = new RegExp("^" + SPC + "?(?:o['\\u2019]clock|Uhr\\b|h\\b)");

function isItalicSpan(italic, s, e, text) {
    var i, n = 0, k = 0;
    if (!italic || !italic.length || e <= s) return false;
    for (i = s; i < e; i++) if (!italic[i]) return false;
    if (e > italic.length) return false;
    for (i = 0; i < text.length && i < italic.length; i++) {
        if (/[A-Za-zÀ-ɏͰ-ϿЀ-ӿא-ת]/.test(text.charAt(i))) { n++; if (italic[i]) k++; }
    }
    if (n && k / n > 0.6) return false;
    if (/[(\[;][    ]*(?:cf\.|vgl\.[    ]*)?$/.test(text.substring(Math.max(0, s - 6), s))) return false;
    return true;
}
function inParens(text, pos) {
    var d = 0, i, ch;
    for (i = 0; i < pos; i++) {
        ch = text.charAt(i);
        if (ch === "(" || ch === "[") d++;
        else if ((ch === ")" || ch === "]") && d) d--;
    }
    return d > 0;
}

// --- Scanner -----------------------------------------------------------------
function Ctx() { this.book = null; this.chapter = null; this.bookSeg = -10000; this.stale = false; }
function copyCtx(c) { var n = new Ctx(); n.book = c.book; n.chapter = c.chapter; n.bookSeg = c.bookSeg; n.stale = c.stale; return n; }

function Scanner(distant) {
    this.pt = new Patterns();
    this.ctx = new Ctx();
    this.distant = distant || 15;
}
Scanner.prototype.heading = function () { this.ctx.stale = true; };
Scanner.prototype.setBook = function (ctx, b, seg) { ctx.book = b; ctx.chapter = null; ctx.bookSeg = seg; ctx.stale = false; };
Scanner.prototype.mk = function (book, c1, v1, s1, x, y, s2) {
    if (x === null || x === undefined) return mkRef(book, c1, v1, s1);
    if (y !== null && y !== undefined) return mkRef(book, c1, v1, s1, x === c1 ? c1 : x, y, s2);
    return mkRef(book, c1, v1, s1, c1, x, s2);
};

// next valid match of a global regex at or after pos, honouring a "no word/char before" rule
function nextMatch(re, text, pos, badBefore) {
    re.lastIndex = pos;
    while (true) {
        var m = re.exec(text);
        if (!m) return null;
        var p = text.charAt(m.index - 1);
        if (m.index > 0 && badBefore(p)) { re.lastIndex = m.index + 1; continue; }
        if (m[0].length === 0) { re.lastIndex = m.index + 1; continue; }
        return m;
    }
}
function badWord(p) { return isW(p); }
function badCv(p) { return isW(p) || p === ":" || p === "." || p === "," || p === "/"; }

Scanner.prototype.scan = function (text, italic, segNo, anchors, ctxIn) {
    var ctx = ctxIn || this.ctx, pt = this.pt, hits = [], snaps = {}, ai = 0, pos = 0, n = text.length;
    var lastBook = null, chain = null, self = this, i;
    anchors = (anchors || []).slice(0);
    anchors.sort(function (a, b) { return a - b; });
    function flush(upto) {
        while (ai < anchors.length && anchors[ai] <= upto) { snaps[anchors[ai]] = copyCtx(ctx); ai++; }
    }
    while (pos < n) {
        var mb = nextMatch(pt.book, text, pos, badWord);
        var mc = nextMatch(pt.cv, text, pos, badCv);
        var mv = nextMatch(pt.vw, text, pos, badWord);
        var best = null, kind = null;
        if (mb) { best = mb; kind = "book"; }
        if (mc && (!best || mc.index < best.index)) { best = mc; kind = "cv"; }
        if (mv && (!best || mv.index < best.index)) { best = mv; kind = "vw"; }
        if (!best) break;
        flush(best.index);
        if (kind === "book") {
            var r = this.book(best, text, italic, ctx, segNo, hits);
            if (!r) { pos = best.index + best[0].length; continue; }
            pos = r[0]; lastBook = r[1]; chain = r[2];
            continue;
        }
        if (kind === "cv") {
            var s = best.index, e = best.index + best[0].length;
            var tm = matchAt(TIME_AFTER, text, e);
            if (tm) { pos = e; continue; }
            var c1 = parseInt(best[1], 10), v1 = parseInt(best[2], 10);
            var rr = this.cv(text, italic, ctx, segNo, hits, s, e, c1, v1, best[3], best[4], best[5], best[6], lastBook, chain);
            pos = rr[0]; lastBook = rr[1]; chain = rr[2];
            continue;
        }
        // verse words
        var vs = best.index, ve = best.index + best[0].length, vlist = best[3];
        var base = vs + best[1].length + best[2].length, im;
        pt.vnum.lastIndex = 0;
        while ((im = pt.vnum.exec(vlist)) !== null) {
            if (im[0].length === 0) { pt.vnum.lastIndex++; continue; }
            var is_ = base + im.index, ie = base + im.index + im[0].length;
            if (ctx.book !== null && ctx.chapter) {
                var v2 = im[3];
                var ref = mkRef(ctx.book, ctx.chapter, parseInt(im[1], 10), im[2] || "",
                    v2 ? ctx.chapter : 0, v2 ? parseInt(v2, 10) : 0, im[4] || "");
                hits.push({start: is_, end: ie, ref: ref, status: refValid(ref) ? "verse-only" : "invalid",
                    raw: text.substring(vs, ve), reason: "chapter " + ctx.chapter + " assumed from context"});
            } else {
                hits.push({start: is_, end: ie, ref: null, status: "unresolved", raw: text.substring(vs, ve),
                    reason: "verse number with no chapter in context"});
            }
        }
        chain = null; lastBook = null; pos = ve;
    }
    flush(n + 1);
    return {hits: hits, snaps: snaps};
};

Scanner.prototype.book = function (m, text, italic, ctx, segNo, hits) {
    var pt = this.pt;
    var start = m.index, nameS = m.index + m[1].length, nameE = nameS + m[2].length;
    var end = m.index + m[0].length;
    var info = resolve(m[2]);
    if (!info) return null;
    var followed = matchAt(pt.cvNext, text, end) || matchAt(pt.afterCh, text, end) ||
        (pt.hcvNext ? matchAt(pt.hcvNext, text, end) : null);
    if (!followed) {
        var cands = candidatesAt(text, nameS), k;
        for (k = 1; k < cands.length; k++) {
            var ce = cands[k].end;
            if (matchAt(pt.cvNext, text, ce) || matchAt(pt.afterCh, text, ce) ||
                (pt.hcvNext ? matchAt(pt.hcvNext, text, ce) : null)) {
                info = cands[k].info; end = ce; nameE = ce; break;
            }
        }
    }
    var bid = info[0], kindS = info[1], shortA = info[2], bareOk = info[3];
    var bk = bookOf(bid);
    var ital = isItalicSpan(italic, nameS, nameE, text);
    var st, ref;

    if (pt.hcv) {
        var hm = matchAt(pt.hcv, text, end);
        if (hm) {
            var c1 = hebToInt(hm.m[1]), v1 = hebToInt(hm.m[2]);
            var x = hm.m[3] ? hebToInt(hm.m[3]) : null, y = hm.m[4] ? hebToInt(hm.m[4]) : null;
            if (c1 && v1 && (!hm.m[3] || x)) {
                ref = this.mk(bid, c1, v1, "", x, y, "");
                st = ital ? "italic" : "explicit";
                if (!refValid(ref)) st = "invalid";
                hits.push({start: start, end: hm.end, ref: ref, status: st, raw: text.substring(start, hm.end), reason: ""});
                if (st === "explicit") {
                    this.setBook(ctx, bid, segNo);
                    ctx.chapter = (ref.c2 && ref.c2 !== ref.c1) ? ref.c2 : ref.c1;
                }
                return [hm.end, null, {book: bid, chapter: ctx.chapter, status: st, end: hm.end}];
            }
        }
    }
    if (matchAt(pt.cvNext, text, end)) {
        if (!ital) this.setBook(ctx, bid, segNo);
        return [end, [bid, end, ital, start], null];
    }
    var xm = matchAt(pt.xch, text, end);
    if (xm) {
        ref = mkRef(bid, parseInt(xm.m[1], 10), 1, "", parseInt(xm.m[2], 10), parseInt(xm.m[3], 10), "");
        st = ital ? "italic" : "explicit";
        if (!refValid(ref)) st = "invalid";
        hits.push({start: start, end: xm.end, ref: ref, status: st, raw: text.substring(start, xm.end), reason: ""});
        if (st === "explicit") { this.setBook(ctx, bid, segNo); ctx.chapter = ref.c2; }
        return [xm.end, null, {book: bid, chapter: ref.c2, status: st, end: xm.end}];
    }
    var cm = matchAt(pt.afterCh, text, end);
    if (cm && !shortA) {
        var c = parseInt(cm.m[1], 10), c2 = cm.m[2] ? parseInt(cm.m[2], 10) : 0;
        if (bk[3] === 1) {
            ref = mkRef(bid, 1, c, "", c2 ? 1 : 0, c2, "");
            st = ital ? "italic" : "explicit";
            if (!refValid(ref)) st = "invalid";
            hits.push({start: start, end: cm.end, ref: ref, status: st, raw: text.substring(start, cm.end), reason: ""});
            if (!ital) { this.setBook(ctx, bid, segNo); ctx.chapter = 1; }
            return [cm.end, null, {book: bid, chapter: 1, status: ital ? "italic" : "explicit", end: cm.end}];
        }
        ref = mkRef(bid, c, 0, "", c2 ? c2 : 0, 0, "");
        st = ital ? "italic" : "chapter-only";
        if (c > bk[3] || (c2 && c2 > bk[3])) st = "invalid";
        hits.push({start: start, end: cm.end, ref: ref, status: st, raw: text.substring(start, cm.end), reason: ""});
        if (!ital && st !== "invalid") { this.setBook(ctx, bid, segNo); ctx.chapter = c2 || c; }
        return [cm.end, null, null];
    }
    var allowed = kindS === "full" && (bareOk || pt.introBefore.test(text.substring(Math.max(0, start - 25), start)));
    if (allowed && !ital) this.setBook(ctx, bid, segNo);
    return [m.index + m[0].length, null, null];
};

Scanner.prototype.cv = function (text, italic, ctx, segNo, hits, s, e, c1, v1, s1, x, y, s2, lastBook, chain) {
    var pt = this.pt, gap = lastBook ? text.substring(lastBook[1], s) : null;
    var ital = isItalicSpan(italic, s, e, text), hitStart = s, book = null, status;
    if (lastBook && pt.attachedGap.test(gap)) {
        book = lastBook[0];
        status = (lastBook[2] || ital) ? "italic" : "explicit";
        hitStart = lastBook[3];
    } else if (chain && chain.book !== null && chain.book !== undefined && pt.chainGap.test(text.substring(chain.end, s))) {
        book = chain.book;
        status = chain.status === "explicit" ? "chain" : chain.status;
        if (ital && status !== "citation") status = "italic";
    } else if (chain && (chain.book === null || chain.book === undefined) && chain.status === "citation" &&
        pt.chainGap.test(text.substring(chain.end, s))) {
        status = "citation";
    } else {
        var pre = text.substring(Math.max(0, s - 60), s);
        if (CITATION_BEFORE.test(pre)) status = "citation";
        else if (ctx.book !== null && (!DATA.rules.bareParens || inParens(text, s))) {
            book = ctx.book;
            status = (ctx.stale || (segNo - ctx.bookSeg) > this.distant) ? "inferred-weak" : "inferred";
            if (ital) status = "italic";
        } else status = "unresolved";
    }
    var ch;
    if (book === null) {
        hits.push({start: s, end: e, ref: null, status: status, raw: text.substring(s, e), reason: status === "citation" ? "volume:page" : ""});
        ch = {book: null, chapter: c1, status: status, end: e};
        return [this.cont(text, e, null, c1, status, hits, ch), null, ch];
    }
    var r = this.mk(book, c1, v1, s1 || "", x ? parseInt(x, 10) : null, y ? parseInt(y, 10) : null, s2 || "");
    if (!refValid(r)) status = "invalid";
    hits.push({start: hitStart, end: e, ref: r, status: status, raw: text.substring(hitStart, e), reason: ""});
    var endCh = (r.c2 && r.c2 !== r.c1) ? r.c2 : r.c1;
    if (INDEXED[status]) { ctx.book = book; ctx.chapter = endCh; }
    ch = {book: book, chapter: endCh, status: status, end: e};
    return [this.cont(text, e, book, endCh, status, hits, ch), null, ch];
};

Scanner.prototype.cont = function (text, pos, book, chapter, status, hits, chain) {
    var pt = this.pt;
    while (true) {
        var m = matchAt(pt.cont, text, pos);
        if (!m || !matchAt(pt.contOkAfter, text, m.end)) return pos;
        var vstart = pos + m.m[1].length;
        pt.book.lastIndex = vstart;
        var bm = pt.book.exec(text);
        if (bm && bm.index === vstart && resolve(bm[2])) return pos;   // the number starts a book name
        if (book === null) {
            hits.push({start: vstart, end: m.end, ref: null, status: status, raw: text.substring(vstart, m.end),
                reason: status === "citation" ? "volume:page" : ""});
        } else {
            var v2 = m.m[4];
            var r = mkRef(book, chapter, parseInt(m.m[2], 10), m.m[3] || "", v2 ? chapter : 0, v2 ? parseInt(v2, 10) : 0, m.m[5] || "");
            var st = status === "explicit" ? "chain" : status;
            if (!refValid(r)) st = "invalid";
            hits.push({start: vstart, end: m.end, ref: r, status: st, raw: text.substring(vstart, m.end), reason: ""});
        }
        chain.end = m.end;
        pos = m.end;
    }
};
